package mx.gob.sedesol.basegestor.gestionescolar.v2;

import static org.testng.Assert.assertEquals;
import static org.testng.Assert.assertFalse;
import static org.testng.Assert.assertTrue;

import java.util.ArrayList;
import java.util.Date;
import java.util.List;

import org.testng.annotations.Test;

import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.CausaIndisponibilidadOfertaV2;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.CausaPendienteUnidadV2;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.CodigoReglaCurricularV2;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.CondicionCurricularV2;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.ContextoEvaluacionCurricularV2DTO;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.EstadoUnidadCurricularV2;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.EvaluacionCargaAcademicaV2DTO;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.ResultadoEvaluacionCurricularV2DTO;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.UnidadEvaluacionCurricularV2DTO;
import mx.gob.sedesol.basegestor.service.impl.gestionescolar.v2.EvaluacionCurricularV2ServiceImpl;

/** F4C-U-01 a F4C-U-25: RN-6.4 efectiva sólo dentro de la propuesta sombra V2. */
public class EvaluacionCurricularV2Fase4CTest {
    private final EvaluacionCurricularV2ServiceImpl service=new EvaluacionCurricularV2ServiceImpl();
    @Test public void f4CU01TresReprobadasMantienenRezagoLeve(){EvaluacionCargaAcademicaV2DTO x=e(c(reprobadas(1L,3))).getEvaluacionCargaAcademica();assertFalse(x.getAplicaRn64());assertTrue(x.getAplicaRn51());assertEquals(x.getCondicionRegularizacion(),"REZAGO_LEVE");}
    @Test public void f4CU02CuatroReprobadasAplicanSevero(){EvaluacionCargaAcademicaV2DTO x=e(c(reprobadas(10L,4))).getEvaluacionCargaAcademica();assertTrue(x.getAplicaRn64());assertFalse(x.getAplicaRn51());assertEquals(x.getCondicionRegularizacion(),"REZAGO_SEVERO");}
    @Test public void f4CU03CincoReprobadasAplicanSevero(){assertTrue(e(c(reprobadas(20L,5))).getEvaluacionCargaAcademica().getAplicaRn64());}
    @Test public void f4CU04SeisReprobadasAplicanSevero(){assertTrue(e(c(reprobadas(30L,6))).getEvaluacionCargaAcademica().getAplicaRn64());}
    @Test public void f4CU05CuatroReprobadasOfertadasSiguenPrioritarias(){EvaluacionCargaAcademicaV2DTO x=e(c(reprobadas(40L,4))).getEvaluacionCargaAcademica();assertEquals(x.getUdsReprobadasOfertadas().size(),4);assertEquals(x.getUdsReprobadasPrioritarias().size(),4);}
    @Test public void f4CU06ObligatoriasNuevasSeBloqueanEnSombra(){ContextoEvaluacionCurricularV2DTO z=c(reprobadas(50L,4));z.getUnidades().add(obligatoria(54L));ResultadoEvaluacionCurricularV2DTO r=e(z);assertTrue(r.getEvaluacionCargaAcademica().getUdsObligatoriasNuevasBloqueadasRn64().contains(Long.valueOf(54L)));assertFalse(r.getDecisiones().get(4).getOfertaEvaluadaV2());}
    @Test public void f4CU07OptativasSoloSonAdicionalesTrasRegularizacion(){ContextoEvaluacionCurricularV2DTO z=c(reprobadas(60L,4));z.getUnidades().add(optativa(64L));EvaluacionCargaAcademicaV2DTO x=e(z).getEvaluacionCargaAcademica();assertTrue(x.getUdsReprobadasPrioritarias().contains(Long.valueOf(60L)));assertTrue(x.getUdsOptativasAdicionalesElegiblesRn64().contains(Long.valueOf(64L)));}
    @Test public void f4CU08NoCursadaNoEvadeRestriccion(){ContextoEvaluacionCurricularV2DTO z=c(reprobadas(70L,4));z.getUnidades().add(obligatoria(74L));EvaluacionCargaAcademicaV2DTO x=e(z).getEvaluacionCargaAcademica();assertTrue(x.getAplicaRn64());assertTrue(x.getUdsObligatoriasNuevasBloqueadasRn64().contains(Long.valueOf(74L)));}
    @Test public void f4CU09BajaParcialNoAumentaConteo(){UnidadEvaluacionCurricularV2DTO baja=obligatoria(85L);baja.setEstado(EstadoUnidadCurricularV2.BAJA_PARCIAL);baja.setCausa(CausaPendienteUnidadV2.BAJA_PARCIAL);List<UnidadEvaluacionCurricularV2DTO> us=reprobadas(80L,4);us.add(baja);ResultadoEvaluacionCurricularV2DTO r=e(c(us));assertEquals(r.getCantidadReprobadasVigentes(),Integer.valueOf(4));assertTrue(r.getEvaluacionCargaAcademica().getAplicaRn64());}
    @Test public void f4CU10TresIntentosMasTresUdsSonCuatro(){UnidadEvaluacionCurricularV2DTO u=reprobada(90L);u.setIntentosFallidosHistoricosConfiables(Integer.valueOf(3));ResultadoEvaluacionCurricularV2DTO r=e(c(u,reprobada(91L),reprobada(92L),reprobada(93L)));assertEquals(r.getCantidadReprobadasVigentes(),Integer.valueOf(4));assertTrue(r.getEvaluacionCargaAcademica().getAplicaRn64());}
    @Test public void f4CU11DosReprobadasSinOfertaConservanRestriccion(){List<UnidadEvaluacionCurricularV2DTO> us=reprobadas(100L,4);us.get(2).setOfertada(Boolean.FALSE);us.get(2).setCausaIndisponibilidadOferta(CausaIndisponibilidadOfertaV2.UD_NO_OFERTADA_PERIODO);us.get(3).setOfertada(Boolean.FALSE);us.get(3).setCausaIndisponibilidadOferta(CausaIndisponibilidadOfertaV2.UD_NO_OFERTADA_PERIODO);EvaluacionCargaAcademicaV2DTO x=e(c(us)).getEvaluacionCargaAcademica();assertTrue(x.getAplicaRn64());assertEquals(x.getUdsReprobadasNoDisponibles().size(),2);}
    @Test public void f4CU12SinCupoSeDistingue(){List<UnidadEvaluacionCurricularV2DTO> us=reprobadas(110L,4);us.get(3).setCupoDisponibleConocido(Boolean.FALSE);us.get(3).setCausaIndisponibilidadOferta(CausaIndisponibilidadOfertaV2.SIN_CUPO);EvaluacionCargaAcademicaV2DTO x=e(c(us)).getEvaluacionCargaAcademica();assertTrue(x.getCausasIndisponibilidadRegularizacion().toString().contains("SIN_CUPO"));assertFalse(x.getCausasIndisponibilidadRegularizacion().toString().contains("SIN_OFERTA"));}
    @Test public void f4CU13ExcepcionMinimaNoEliminaSevero(){List<UnidadEvaluacionCurricularV2DTO> us=reprobadas(120L,4);us.get(2).setOfertada(Boolean.FALSE);us.get(3).setOfertada(Boolean.FALSE);EvaluacionCargaAcademicaV2DTO x=e(c(us)).getEvaluacionCargaAcademica();assertTrue(x.getAplicaRn64());assertTrue(x.getExcepcionMinimoAplicable());}
    @Test public void f4CU14MaximoSigueSiendoSeis(){assertEquals(e(c(reprobadas(130L,4))).getEvaluacionCargaAcademica().getCargaMaximaNormativa(),Integer.valueOf(6));}
    @Test public void f4CU15Rn64PrevaleceSobreAvanceQuinto(){ContextoEvaluacionCurricularV2DTO z=c(reprobadas(140L,4));z.setSemestreObjetivo(Integer.valueOf(5));z.setPeriodoNormativo("2027-1");z.setAvanceCondicionado(Boolean.TRUE);ResultadoEvaluacionCurricularV2DTO r=e(z);assertTrue(r.getEvaluacionCargaAcademica().getCtr01Rn61Procedente());assertTrue(r.getEvaluacionCargaAcademica().getAvanceCondicionadoBloqueadoPorRn64());assertFalse(r.getAvanceCondicionado());}
    @Test public void f4CU16TerceroNoActivaRn61(){ContextoEvaluacionCurricularV2DTO z=c(reprobadas(150L,4));z.setPeriodoNormativo("2027-1");assertFalse(e(z).getEvaluacionCargaAcademica().getCtr01Rn61Procedente());}
    @Test public void f4CU17SeptimoNoActivaRn61(){ContextoEvaluacionCurricularV2DTO z=c(reprobadas(160L,4));z.setSemestreObjetivo(Integer.valueOf(7));z.setPeriodoNormativo("2027-1");assertFalse(e(z).getEvaluacionCargaAcademica().getCtr01Rn61Procedente());}
    @Test public void f4CU18CincoMenosUnaPermaneceSevero(){assertTrue(e(c(reprobadas(170L,4))).getEvaluacionCargaAcademica().getAplicaRn64());}
    @Test public void f4CU19CuatroMenosUnaVuelveARezagoLeve(){EvaluacionCargaAcademicaV2DTO x=e(c(reprobadas(180L,3))).getEvaluacionCargaAcademica();assertFalse(x.getAplicaRn64());assertTrue(x.getAplicaRn51());assertEquals(x.getCondicionRegularizacion(),"REZAGO_LEVE");}
    @Test public void f4CU20AcreditarTodasNoDeclaraRegularidadPorRn64(){ResultadoEvaluacionCurricularV2DTO r=e(c(acreditada(190L),acreditada(191L),acreditada(192L),acreditada(193L)));assertFalse(r.getEvaluacionCargaAcademica().getAplicaRn64());assertEquals(r.getSituacionAcademicaCalculada(),"REGULAR");}
    @Test public void f4CU21EmpatePrioritarioSinEspacioRequiereRevision(){EvaluacionCargaAcademicaV2DTO x=e(c(reprobadas(200L,7))).getEvaluacionCargaAcademica();assertTrue(x.getRequiereRevisionRegularizacion());assertEquals(x.getUdsEmpatadasRegularizacion().size(),7);}
    @Test public void f4CU22DuplicadoNoDuplicaReprobadas(){UnidadEvaluacionCurricularV2DTO a=reprobada(210L),b=reprobada(210L);a.setBloque("B1");b.setBloque("B2");ResultadoEvaluacionCurricularV2DTO r=e(c(a,b,reprobada(211L),reprobada(212L),reprobada(213L)));assertEquals(r.getCantidadReprobadasVigentes(),Integer.valueOf(4));assertTrue(r.getEvaluacionCargaAcademica().getAplicaRn64());}
    @Test public void f4CU23DatosInsuficientesNoInfiere(){EvaluacionCargaAcademicaV2DTO x=e(c(indeterminada(220L))).getEvaluacionCargaAcademica();assertFalse(x.getAplicaRn64());assertTrue(x.getRequiereRevision());}
    @Test public void f4CU24MismoContextoEsDeterminista(){ContextoEvaluacionCurricularV2DTO z=c(reprobadas(230L,4));assertEquals(e(z).getEvaluacionCargaAcademica().getCondicionRegularizacion(),e(z).getEvaluacionCargaAcademica().getCondicionRegularizacion());}
    @Test public void f4CU25NoTieneEfectoProductivo(){UnidadEvaluacionCurricularV2DTO u=reprobada(240L);ResultadoEvaluacionCurricularV2DTO r=e(c(u,reprobada(241L),reprobada(242L),reprobada(243L)));assertFalse(r.getEfectosProductivosAplicados());assertTrue(u.getOfertada());assertTrue(r.getReglasEvaluadas().contains(CodigoReglaCurricularV2.RN_6_4));assertTrue(r.getCondicionesDetectadas().contains(CondicionCurricularV2.REZAGO_SEVERO));}
    private ResultadoEvaluacionCurricularV2DTO e(ContextoEvaluacionCurricularV2DTO z){return service.evaluarSombra(z);} private ContextoEvaluacionCurricularV2DTO c(UnidadEvaluacionCurricularV2DTO...us){ContextoEvaluacionCurricularV2DTO z=new ContextoEvaluacionCurricularV2DTO();z.setVersionReglas("PE2027-V1");z.setFechaEvaluacion(new Date(0L));z.setSemestreObjetivo(Integer.valueOf(3));z.setActividadAcademicaComprobada(Boolean.TRUE);z.setPermanenciaDentroLimiteComprobada(Boolean.TRUE);z.setDictaminacionEgresoConocida(Boolean.TRUE);z.setOportunidadesMejoraUtilizadas(Integer.valueOf(0));for(UnidadEvaluacionCurricularV2DTO u:us)z.getUnidades().add(u);return z;} private ContextoEvaluacionCurricularV2DTO c(List<UnidadEvaluacionCurricularV2DTO> us){return c(us.toArray(new UnidadEvaluacionCurricularV2DTO[us.size()]));}
    private List<UnidadEvaluacionCurricularV2DTO> reprobadas(Long i,int n){List<UnidadEvaluacionCurricularV2DTO> r=new ArrayList<UnidadEvaluacionCurricularV2DTO>();for(int x=0;x<n;x++)r.add(reprobada(Long.valueOf(i.longValue()+x)));return r;} private UnidadEvaluacionCurricularV2DTO obligatoria(Long i){return pendiente(i,"Obligatoria");} private UnidadEvaluacionCurricularV2DTO optativa(Long i){return pendiente(i,"Optativa");} private UnidadEvaluacionCurricularV2DTO reprobada(Long i){UnidadEvaluacionCurricularV2DTO u=pendiente(i,"Obligatoria");u.setEstado(EstadoUnidadCurricularV2.REPROBADA);u.setCausa(CausaPendienteUnidadV2.REPROBACION);u.setReprobacionVigenteConocida(Boolean.TRUE);u.setReprobacionPeriodoPrevioConocida(Boolean.TRUE);return u;} private UnidadEvaluacionCurricularV2DTO acreditada(Long i){UnidadEvaluacionCurricularV2DTO u=pendiente(i,"Obligatoria");u.setEstado(EstadoUnidadCurricularV2.ACREDITADA);u.setCausa(null);return u;} private UnidadEvaluacionCurricularV2DTO indeterminada(Long i){UnidadEvaluacionCurricularV2DTO u=pendiente(i,"Obligatoria");u.setEstado(EstadoUnidadCurricularV2.NO_DETERMINADO);u.setCausa(null);return u;} private UnidadEvaluacionCurricularV2DTO pendiente(Long i,String t){UnidadEvaluacionCurricularV2DTO u=new UnidadEvaluacionCurricularV2DTO();u.setIdPrograma(i);u.setClave("UD"+i);u.setTipoUd(t);u.setEstado(EstadoUnidadCurricularV2.NO_CURSADA);u.setCausa(CausaPendienteUnidadV2.NO_CURSAMIENTO);u.setOfertada(Boolean.TRUE);u.setGrupoActivoConocido(Boolean.TRUE);u.setCupoDisponibleConocido(Boolean.TRUE);u.setSeleccionableOrigen(Boolean.TRUE);return u;}
}
